def transform(grid):
    border = grid[0][0]
    filled_rows = {r for r, row in enumerate(grid) if 2 in row}
    filled_cols = {c for c in range(len(grid[0])) if any(row[c] == 2 for row in grid)}
    if len(filled_rows) <= len(filled_cols):
        return [[(border if r in filled_rows else 0) if x in (0, border) else x for x in row] for r, row in enumerate(grid)]
    return [[(border if c in filled_cols else 0) if x in (0, border) else x for c, x in enumerate(row)] for row in grid]

